<script setup lang="ts">
import PersonAvatar from './PersonAvatar.vue'
import ProfileView from './ProfileView.vue'
import { unitLabel,unitPath } from '~~/shared/utils/team'
import type { TeamDirectory,TeamPerson } from '~~/shared/types/team'
const props=defineProps<{profileId?:string}>()
const team=useTeamStore(),data=ref<TeamDirectory|null>(null),query=ref(''),company=ref('all'),page=ref(1),view=ref<'people'|'structure'>('structure'),loading=ref(false),error=ref('')
let sequence=0,timer:ReturnType<typeof setTimeout>|undefined
async function load(force=false){if(props.profileId)return;const current=++sequence;loading.value=true;error.value='';try{const result=await team.directory(query.value,page.value,company.value==='all'?'':company.value,force);if(current===sequence)data.value=result}catch(failure:any){if(current===sequence)error.value=failure?.data?.message||'Команда недоступна'}finally{if(current===sequence)loading.value=false}}
watch([query,company],()=>{page.value=1;clearTimeout(timer);timer=setTimeout(()=>load(),300)})
watch(page,()=>load())
watch(()=>props.profileId,()=>load(),{immediate:true})
const companyOptions=computed(()=>[{label:'Все компании',value:'all'},...(data.value?.units.filter(unit=>unit.kind==='company')??[]).map(unit=>({label:unit.name,value:unit.id}))])
const structure=computed(()=>{
 const units=data.value?.units??[],people=data.value?.people??[]
 return units.filter(unit=>unit.kind==='company'&&(company.value==='all'||unit.id===company.value)).map(company=>({company,departments:units.filter(unit=>unit.parentId===company.id&&unit.kind==='department').map(department=>({department,people:people.filter(person=>person.roleIds.includes(department.id)&&!person.roleIds.some(id=>unitPath(id,units).some(item=>item.id===department.id)&&units.find(item=>item.id===id)?.kind==='role')),roles:units.filter(unit=>unit.parentId===department.id&&unit.kind==='role').map(role=>({role,people:people.filter(person=>person.roleIds.includes(role.id))}))})),unassigned:people.filter(person=>!person.roleIds.length&&person.brand===company.brand||person.roleIds.includes(company.id)&&!person.roleIds.some(id=>id!==company.id&&unitPath(id,units)[0]?.id===company.id))}))
})
const positions=(person:TeamPerson)=>person.roleIds.map(id=>unitLabel(id,data.value?.units??[]))
const matchCompany=(person:TeamPerson,id:string)=>person.roleIds.some(role=>unitPath(role,data.value?.units??[])[0]?.id===id)||!person.roleIds.length&&data.value?.units.find(unit=>unit.id===id)?.brand===person.brand
onBeforeUnmount(()=>{sequence++;clearTimeout(timer)})
</script>
<template><ProfileView v-if="profileId" :user-id="profileId"/><div v-else class="team-page"><div class="team-page-heading"><div><h1>Команда</h1><p>Компании, отделы и люди, с которыми вы работаете.</p></div><UButton to="/profile" color="neutral" variant="outline" icon="i-lucide-user-round" label="Мой профиль"/></div><div class="team-toolbar"><UInput v-model="query" icon="i-lucide-search" placeholder="ФИО, почта или Telegram" aria-label="Найти участника"/><USelect v-model="company" :items="companyOptions" aria-label="Компания"/><div class="team-view-switch"><button :class="{selected:view==='structure'}" @click="view='structure'"><UIcon name="i-lucide-git-fork"/>Структура</button><button :class="{selected:view==='people'}" @click="view='people'"><UIcon name="i-lucide-users"/>Участники</button></div><UButton color="neutral" variant="ghost" icon="i-lucide-refresh-cw" aria-label="Обновить команду" :loading="loading" @click="load(true)"/></div><UAlert v-if="error" color="error" :description="error" class="mb-5"/><p class="team-result-count">{{ data?.total??0 }} участников<template v-if="loading"> · Загружаем…</template></p><div v-if="view==='people'" class="team-person-grid"><NuxtLink v-for="person in data?.people??[]" :key="person.id" :to="`/team/${person.id}`" class="team-person-card"><PersonAvatar :name="person.fullName||person.email" :src="person.avatarUrl"/><strong>{{ person.fullName||person.email }}</strong><span>{{ person.workEmail||person.email }}</span><small v-if="person.telegram">@{{ person.telegram }}</small><div class="team-position-tags"><span v-for="label in positions(person)" :key="label">{{ label }}</span><span v-if="!person.roleIds.length">{{ person.brand==='light'?'Light':'Magnat' }} · Без отдела</span></div><small v-if="person.commonVaultCount">{{ person.commonVaultCount }} общих хранилищ</small></NuxtLink></div><div v-else class="team-organization"><section v-for="branch in structure" v-show="!query.trim()||(data?.people??[]).some(person=>matchCompany(person,branch.company.id))" :key="branch.company.id" class="team-company"><header><span :class="['team-company-mark',branch.company.brand]">{{ branch.company.name.slice(0,1) }}</span><div><h2>{{ branch.company.name }}</h2><p>Компания → отдел → должность → участник</p></div></header><div class="team-departments"><section v-for="item in branch.departments" :key="item.department.id" class="team-department"><h3><UIcon name="i-lucide-git-branch"/>{{ item.department.name }}</h3><NuxtLink v-for="person in item.people" :key="person.id" :to="`/team/${person.id}`" class="team-member-link"><PersonAvatar :name="person.fullName||person.email" :src="person.avatarUrl"/><span><strong>{{ person.fullName||person.email }}</strong><small>Отдел назначен · Должность не указана</small></span><UIcon name="i-lucide-arrow-up-right"/></NuxtLink><div v-for="group in item.roles" :key="group.role.id" class="team-job-group"><h4>{{ group.role.name }} <span>{{ group.people.length }}</span></h4><NuxtLink v-for="person in group.people" :key="person.id" :to="`/team/${person.id}`" class="team-member-link"><PersonAvatar :name="person.fullName||person.email" :src="person.avatarUrl"/><span><strong>{{ person.fullName||person.email }}</strong><small>{{ person.workEmail||person.email }}</small></span><UIcon name="i-lucide-arrow-up-right"/></NuxtLink><p v-if="!group.people.length" class="team-muted">На этой странице нет участников с такой должностью.</p></div><p v-if="!item.roles.length" class="team-muted">Должности ещё не добавлены.</p></section><section v-if="branch.unassigned.length" class="team-department"><h3><UIcon name="i-lucide-user-round"/>Без отдела</h3><p class="team-muted">Администратор может назначить этим участникам отдел и должность.</p><NuxtLink v-for="person in branch.unassigned" :key="person.id" :to="`/team/${person.id}`" class="team-member-link"><PersonAvatar :name="person.fullName||person.email" :src="person.avatarUrl"/><span><strong>{{ person.fullName||person.email }}</strong><small>{{ person.workEmail||person.email }}</small></span><UIcon name="i-lucide-arrow-up-right"/></NuxtLink></section></div></section></div><p v-if="!loading&&!data?.people.length" class="team-empty">Участники не найдены. Попробуйте другой запрос.</p><div v-if="(data?.total??0)>50" class="team-pagination"><UButton color="neutral" variant="outline" label="Назад" :disabled="page<=1||loading" @click="page--"/><span>{{ page }} / {{ Math.ceil((data?.total??0)/50) }} · На схеме показаны участники текущей страницы</span><UButton color="neutral" variant="outline" label="Далее" :disabled="page>=Math.ceil((data?.total??0)/50)||loading" @click="page++"/></div></div></template>
